import { TEFF_BPRP } from './teffTable.gen';

/**
 * Star colour: Gaia BP-RP -> effective temperature -> blackbody chromaticity
 * -> linear sRGB with unit luminance.
 *
 * BP-RP -> Teff uses an empirical table measured from our own catalogue:
 * the median Gaia DR3 GSP-Phot temperature per 0.1 mag colour bin for
 * low-extinction stars within 250 pc (teffTable.gen.ts). The colour is that of a Planck spectrum integrated
 * against the CIE 1931 2° colour-matching functions (Wyman, Sloan & Shirley
 * 2013 analytic fit), converted to linear sRGB (D65).
 */

/** CIE 1931 2° CMFs, multi-lobe Gaussian fit (Wyman et al. 2013, JCGT 2(2)). */
function cie(lambdaNm: number): [number, number, number] {
  const g = (x: number, mu: number, s1: number, s2: number) => {
    const t = (x - mu) / (x < mu ? s1 : s2);
    return Math.exp(-0.5 * t * t);
  };
  const x = 1.056 * g(lambdaNm, 599.8, 37.9, 31.0) + 0.362 * g(lambdaNm, 442.0, 16.0, 26.7) - 0.065 * g(lambdaNm, 501.1, 20.4, 26.2);
  const y = 0.821 * g(lambdaNm, 568.8, 46.9, 40.5) + 0.286 * g(lambdaNm, 530.9, 16.3, 31.1);
  const z = 1.217 * g(lambdaNm, 437.0, 11.8, 36.0) + 0.681 * g(lambdaNm, 459.0, 26.0, 13.8);
  return [x, y, z];
}

function planck(lambdaNm: number, T: number): number {
  const l = lambdaNm * 1e-9;
  const c2 = 1.438777e-2; // m K
  return 1 / (l ** 5 * (Math.exp(c2 / (l * T)) - 1));
}

/** Linear sRGB of a blackbody at temperature T, normalised to luminance 1. */
export function blackbodyRgb(T: number): [number, number, number] {
  let X = 0, Y = 0, Z = 0;
  for (let l = 380; l <= 780; l += 5) {
    const p = planck(l, T);
    const [x, y, z] = cie(l);
    X += p * x;
    Y += p * y;
    Z += p * z;
  }
  X /= Y;
  Z /= Y;
  Y = 1;
  // XYZ -> linear sRGB (D65)
  let r = 3.2404542 * X - 1.5371385 * Y - 0.4985314 * Z;
  let g = -0.969266 * X + 1.8760108 * Y + 0.041556 * Z;
  let b = 0.0556434 * X - 0.2040259 * Y + 1.0572252 * Z;
  // out-of-gamut (very hot/cool): desaturate towards white keeping luminance
  const m = Math.min(r, g, b);
  if (m < 0) {
    const k = -m / (1 - m);
    r = r * (1 - k) + k;
    g = g * (1 - k) + k;
    b = b * (1 - k) + k;
  }
  const L = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return [r / L, g / L, b / L];
}

/** Gaia BP-RP -> Teff (K): piecewise-linear in the empirical table. */
export function teffFromBpRp(c: number): number {
  const t = TEFF_BPRP;
  if (c <= t[0][0]) return t[0][1];
  for (let i = 1; i < t.length; i++) {
    if (c <= t[i][0]) {
      const f = (c - t[i - 1][0]) / (t[i][0] - t[i - 1][0]);
      return t[i - 1][1] + (t[i][1] - t[i - 1][1]) * f;
    }
  }
  return t[t.length - 1][1];
}

/** 256-entry LUT indexed like the octree colour byte (bp_rp = -0.6 + 0.02 q). */
export function buildColorLut(saturation = 1.0): Float32Array {
  const lut = new Float32Array(256 * 4);
  for (let q = 0; q < 256; q++) {
    const c = -0.6 + 0.02 * q;
    const [r, g, b] = blackbodyRgb(teffFromBpRp(c));
    const L = 1;
    lut[q * 4] = L + (r - L) * saturation;
    lut[q * 4 + 1] = L + (g - L) * saturation;
    lut[q * 4 + 2] = L + (b - L) * saturation;
    lut[q * 4 + 3] = teffFromBpRp(c);
  }
  return lut;
}
