/// <reference lib="webworker" />
/**
 * Decodes Milky Way cube faces (WebP RGB: 16-bit log surface brightness in
 * R,G; colour byte in B) into half-float RGBA radiance, linear sRGB.
 */
import { buildColorLut } from '../render/starColor';

const lut = buildColorLut(1.0);

function toHalf(v: number): number {
  // float32 -> float16 bits (round to nearest), sufficient for radiance
  const f = new Float32Array(1);
  const i = new Uint32Array(f.buffer);
  f[0] = v;
  const x = i[0];
  const sign = (x >>> 16) & 0x8000;
  let e = ((x >>> 23) & 0xff) - 127 + 15;
  let m = x & 0x7fffff;
  if (e <= 0) return sign;
  if (e >= 31) return sign | 0x7c00;
  m = m + 0x1000;
  if (m & 0x800000) {
    m = 0;
    e += 1;
    if (e >= 31) return sign | 0x7c00;
  }
  return sign | (e << 10) | (m >>> 13);
}

self.onmessage = async (ev: MessageEvent<{ urls: string[]; logMin: number; logMax: number; key: string }>) => {
  const { urls, logMin, logMax, key } = ev.data;
  const faces: Uint16Array[] = [];
  let size = 0;
  for (const url of urls) {
    const blob = await (await fetch(url)).blob();
    const bmp = await createImageBitmap(blob, { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
    size = bmp.width;
    const c = new OffscreenCanvas(bmp.width, bmp.height);
    const ctx = c.getContext('2d', { willReadFrequently: true })!;
    ctx.drawImage(bmp, 0, 0);
    const px = ctx.getImageData(0, 0, bmp.width, bmp.height, { colorSpace: 'srgb' }).data;
    const out = new Uint16Array(bmp.width * bmp.height * 4);
    const span = logMax - logMin;
    for (let i = 0, j = 0; i < px.length; i += 4, j += 4) {
      const q = (px[i] * 256 + px[i + 1]) / 65535;
      const L = q <= 0 ? 0 : Math.pow(10, logMin + q * span) - 1e-3;
      const ci = px[i + 2] * 4;
      out[j] = toHalf(Math.max(0, L * lut[ci]));
      out[j + 1] = toHalf(Math.max(0, L * lut[ci + 1]));
      out[j + 2] = toHalf(Math.max(0, L * lut[ci + 2]));
      out[j + 3] = toHalf(1);
    }
    faces.push(out);
  }
  (self as unknown as Worker).postMessage({ key, size, faces }, faces.map((f) => f.buffer));
};
